  if (h == null || h === '') return null;
  const fa = '۰۱۲۳۴۵۶۷۸۹';
  const s = String(h).replace(/[۰-۹]/g, d => fa.indexOf(d)).replace('٫', '.');
  const m = s.match(/[\d.]+/);
